data Pool = Pool String [String]
instance FromJSON Pool where parseJSON=withObject "pool" $ \o -> Pool <$> o .: "pool" <*> o .: "weights"
data Case = Case {cid::String,oldPot::Integer,pot::Integer,history::[Pool],fresh::[Pool],admitted::Bool}
instance FromJSON Case where parseJSON=withObject "case" $ \o -> Case <$> o .: "id" <*> (read <$> o .: "oldPot") <*> (read <$> o .: "pot") <*> o .: "history" <*> o .: "fresh" <*> o .: "scalaAdmitted"
newtype Input=Input [Case]
instance FromJSON Input where parseJSON=withObject "input" (\o -> Input <$> o .: "cases")
word s=case readHex s of [(n,"")] -> n; _ -> error "invalid admitted hex"
hex n width=let h=showHex n "" in replicate (width-length h) '0'++h
weights bs=Likelihood $ snd $ mapAccumL assign (map (word :: String -> Word32) bs) template
  where
    template=unLikelihood (likelihood 0 0 (EpochSize 1))
    assign (b:rest) _=(rest,LogWeight (castWord32ToFloat b))
    assign [] _=error "admitted vector length"
poolMap ps=VM.fromList [(R.key (word (take 2 k)),weights ws) | Pool k ws <- ps]
likelihoodJSON l=map (\(LogWeight f)->hex (castFloatToWord32 f) 8) (toList (unLikelihood l))
stateJSON NonMyopic{..}=object ["rewardPot" .= R.coinText rewardPotNM,"likelihoods" .=
  [object ["pool" .= R.keyText k,"weights" .= likelihoodJSON l] | (k,l)<-VM.toList likelihoodsNM]]
runCase Case{..}=object ["id" .= cid,"scalaAdmitted" .= admitted,"after" .= stateJSON
  (updateNonMyopic (NonMyopic (poolMap history) (Coin oldPot)) (Coin pot) (poolMap fresh))]
emptyProbe fee=object ["fees" .= R.dec fee,"completed" .= stateJSON (nonMyopic ru),"applied" .= stateJSON (esNonMyopic applied)]
  where
    c=R.Case "empty-native" fee 0 0 True False 100 False []
    es=(R.esFor c){esNonMyopic=NonMyopic (poolMap [Pool (replicate 56 '1') (replicate 100 "40e00000")]) (Coin 99)}
    initial=startStep (EpochSize 500) (R.blockMap c) es (Coin 2000) (activeSlotCoeff (R.globals c)) (securityParameter (R.globals c))
    complete=fst $ runReader (completeStep initial) (R.globals c)
    ru=case complete of Complete x->x; _->error "not complete"
    applied=fst $ applyRUpdFiltered ru es
generatorProbe blocks sigma=object ["blocks" .= R.dec blocks,"sigma" .= R.ratioJSON sigma,
  "leaderProbabilityBits" .= hex (castDoubleToWord64 t) 16,"weights" .= likelihoodJSON (likelihood blocks t (EpochSize 500))]
  where t=leaderProbability (activeSlotCoeff (R.globals (R.Case "x" 0 0 0 True False 100 False []))) sigma (R.unit 0)
main=do
  args<-getArgs
  input<-case args of [path]->withBinaryFile path ReadMode (\h->BS.hGet h 65537); _->fail "usage: synthetic-reward-diff cases.json"
  unless (input==canonical) $ fail "exact canonical diagnostic required"
  Input cs<-either fail pure (eitherDecodeStrict' input)
  BL.putStrLn $ encode $ object ["schema" .= ("non-myopic-diagnostic-result-v1"::String),"inputSha256" .= ("b90a463584e1018a2185023cecb82e1558548fa915b1f57cfe06381820b4d235"::String),
    "producer" .= ("native"::String), "cases" .= map runCase cs,"emptyProbes" .= map emptyProbe [0,37],
    "generationProbes" .= [generatorProbe 0 (1%13),generatorProbe 1 (1%13),generatorProbe 0 0]]
